<script setup>
import messageApi from '@/utils/messageApi'
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { Bell, Calendar, Check, EditPen, Plus, Search, Setting, Delete } from '@element-plus/icons-vue'
import { ElMessageBox } from 'element-plus'
import Nav from '@/components/Nav.vue'
import request from '@/utils/request'
import { useTheme } from '@/composables/useTheme'

const { isDark } = useTheme()
const route = useRoute()
const router = useRouter()
const menuItems = [
  { key: 'today', label: '今日工作台', icon: '📋', path: '/Today' },
  { key: 'work', label: '职场工作台', icon: '💼', path: '/WorkRecords' },
  { key: 'growth', label: '成长规划', icon: '🌱', path: '/GrowthPlanner' },
]
const quadrants = [
  { key: 'IMPORTANT_URGENT', label: '重要 · 紧急', subtitle: '立即处理', tone: 'rose' },
  { key: 'IMPORTANT_NOT_URGENT', label: '重要 · 不紧急', subtitle: '安排时间', tone: 'green' },
  { key: 'URGENT_NOT_IMPORTANT', label: '紧急 · 不重要', subtitle: '尽量委托', tone: 'cyan' },
  { key: 'NOT_IMPORTANT_NOT_URGENT', label: '不重要 · 不紧急', subtitle: '稍后处理', tone: 'slate' },
]
const today = new Date().toISOString().slice(0, 10)
const dateOnly = (value) => value ? String(value).replace('T', ' ').slice(0, 10) : ''
const formatDate = (value) => { const date = dateOnly(value); return !date ? '未定日期' : date === today ? '今天' : date < today ? '逾期 · ' + date : date }
const unwrap = (response) => Array.isArray(response?.data) ? response.data : Array.isArray(response?.data?.records) ? response.data.records : []
const emptyTask = (quadrant) => ({ id: null, goalId: null, taskName: '', taskType: 'FOCUS', status: 'TODO', priority: quadrant?.startsWith('IMPORTANT') ? 'HIGH' : 'MEDIUM', quadrant: quadrant || 'IMPORTANT_NOT_URGENT', startDate: today, dueDate: today, estimatedMinutes: 30, actualMinutes: 0, outcome: '', notes: '', tags: '', reminderEnabled: 0, reminderAt: '', repeatRule: 'NONE' })
const activeView = ref('matrix')
const loading = ref(false)
const saving = ref(false)
const tasks = ref([])
const goals = ref([])
const searchText = ref('')
const statusFilter = ref('ACTIVE')
const showForm = ref(false)
const draggedId = ref(null)
const editingTask = ref(null)
const form = ref(emptyTask())
const error = ref('')
const reportRange = ref('week')
const notificationPreference = ref({ enabled: 1, quietHoursEnabled: 0, quietStart: '22:00', quietEnd: '08:00', defaultReminderMinutes: 10, defaultStartTime: '09:00', defaultEndTime: '18:00', browserNotificationsEnabled: 0 })

const visibleTasks = computed(() => tasks.value.filter((item) => {
  const statusOk = statusFilter.value === 'ALL' || (statusFilter.value === 'ACTIVE' ? item.status !== 'DONE' : item.status === 'DONE')
  const text = ((item.taskName || '') + ' ' + (item.notes || '') + ' ' + (item.tags || '')).toLowerCase()
  return statusOk && (!searchText.value.trim() || text.includes(searchText.value.trim().toLowerCase()))
}))
const activeTasks = computed(() => tasks.value.filter((item) => item.status !== 'DONE'))
const completedTasks = computed(() => tasks.value.filter((item) => item.status === 'DONE'))
const listTasks = computed(() => {
  if (activeView.value === 'today') {
    return visibleTasks.value.filter((item) => item.status !== 'DONE' && item.dueDate && dateOnly(item.dueDate) <= today)
  }
  if (activeView.value === 'completed') {
    return visibleTasks.value.filter((item) => item.status === 'DONE')
  }
  return visibleTasks.value
})
const quadrantTasks = (key) => visibleTasks.value.filter((item) => (item.quadrant || 'NOT_IMPORTANT_NOT_URGENT') === key)
const quadrantLabel = (key) => quadrants.find((item) => item.key === key)?.label || '未分类'
const matrixCount = computed(() => activeTasks.value.length)
const overdueCount = computed(() => activeTasks.value.filter((item) => dateOnly(item.dueDate) && dateOnly(item.dueDate) < today).length)
const todayDueCount = computed(() => activeTasks.value.filter((item) => dateOnly(item.dueDate) === today).length)
const completionRate = computed(() => tasks.value.length ? Math.round(completedTasks.value.length * 100 / tasks.value.length) : 0)
const quadrantStats = computed(() => quadrants.map((quadrant) => { const all = tasks.value.filter((item) => (item.quadrant || 'NOT_IMPORTANT_NOT_URGENT') === quadrant.key); return { ...quadrant, total: all.length, done: all.filter((item) => item.status === 'DONE').length } }))
const reportDays = computed(() => {
  const count = reportRange.value === 'month' ? 30 : reportRange.value === 'quarter' ? 90 : 7
  return Array.from({ length: count }, (_, index) => {
    const date = new Date(); date.setDate(date.getDate() - count + index + 1)
    const key = date.toISOString().slice(0, 10)
    return { key, label: (date.getMonth() + 1) + '/' + date.getDate(), done: completedTasks.value.filter((item) => dateOnly(item.completedAt || item.updatedAt || item.updateTime) === key).length }
  })
})
const maxReportDone = computed(() => Math.max(1, ...reportDays.value.map((item) => item.done)))
const activeDays = computed(() => new Set(reportDays.value.filter((item) => item.done).map((item) => item.key)).size)

const loadData = async () => {
  loading.value = true; error.value = ''
  try {
    const result = await Promise.allSettled([request.get('/workplace/tasks'), request.get('/workplace/goals'), request.get('/notifications/preference')])
    tasks.value = result[0].status === 'fulfilled' ? unwrap(result[0].value) : []
    goals.value = result[1].status === 'fulfilled' ? unwrap(result[1].value) : []
    if (result[2].status === 'fulfilled' && result[2].value?.data) notificationPreference.value = { ...notificationPreference.value, ...result[2].value.data }
    if (result.some((item) => item.status === 'rejected')) error.value = '部分数据暂时不可用，仍可继续编辑已加载的任务。'
  } finally { loading.value = false }
}
const openCreate = (quadrant) => { editingTask.value = null; form.value = emptyTask(quadrant); showForm.value = true }
const editTask = (task) => { editingTask.value = task; form.value = { ...emptyTask(task.quadrant), ...task, reminderAt: task.reminderAt || '' }; showForm.value = true }
const closeForm = () => { showForm.value = false; editingTask.value = null }
const saveTask = async () => {
  if (!form.value.taskName.trim()) return messageApi.warning('请填写任务名称')
  saving.value = true
  try {
    await request.post('/workplace/tasks', { ...form.value, taskName: form.value.taskName.trim(), startDate: form.value.startDate || null, dueDate: form.value.dueDate || null, reminderEnabled: form.value.reminderEnabled ? 1 : 0, reminderAt: form.value.reminderEnabled ? (form.value.reminderAt || null) : null, tags: form.value.tags?.trim() || null, notes: form.value.notes?.trim() || null })
    messageApi.success(editingTask.value ? '任务已更新' : '任务已创建'); closeForm(); await loadData()
  } catch (taskError) { messageApi.error(taskError?.message || '任务保存失败') } finally { saving.value = false }
}
const saveStatus = async (task, status) => { try { await request.post('/workplace/tasks', { ...task, status }); await loadData(); messageApi.success(status === 'DONE' ? '任务已完成' : '任务已恢复') } catch (taskError) { messageApi.error(taskError?.message || '任务状态更新失败') } }
const deleteTask = async (task) => {
  try { await ElMessageBox.confirm('确认删除任务“' + (task.taskName || '未命名任务') + '”？', '删除任务', { type: 'warning' }); await request.delete('/workplace/tasks/' + task.id); if (editingTask.value?.id === task.id) closeForm(); await loadData(); messageApi.success('任务已删除') }
  catch (taskError) { if (taskError !== 'cancel' && taskError !== 'close') messageApi.error(taskError?.message || '删除失败') }
}
const startDrag = (event, task) => { draggedId.value = task.id; event.dataTransfer.effectAllowed = 'move'; event.dataTransfer.setData('text/plain', String(task.id)) }
const dropToQuadrant = async (event, quadrant) => { event.preventDefault(); const id = draggedId.value || event.dataTransfer.getData('text/plain'); const task = tasks.value.find((item) => String(item.id) === String(id)); draggedId.value = null; if (!task || task.quadrant === quadrant) return; try { await request.post('/workplace/tasks', { ...task, quadrant }); await loadData(); messageApi.success('已移动到' + quadrantLabel(quadrant)) } catch (taskError) { messageApi.error(taskError?.message || '移动失败') } }
const goView = (view) => { activeView.value = view; statusFilter.value = view === 'completed' ? 'DONE' : view === 'today' ? 'ACTIVE' : statusFilter.value; router.replace({ path: '/TaskMatrix', query: { view } }) }
const savePreference = async () => { try { const response = await request.put('/notifications/preference', notificationPreference.value); notificationPreference.value = { ...notificationPreference.value, ...(response.data || {}) }; messageApi.success('提醒偏好已保存') } catch (preferenceError) { messageApi.error(preferenceError?.message || '提醒偏好保存失败') } }
const requestBrowserPermission = async () => { if (!('Notification' in window)) return messageApi.warning('当前浏览器不支持系统通知'); const permission = await Notification.requestPermission(); if (permission === 'granted') { notificationPreference.value.browserNotificationsEnabled = 1; await savePreference(); new Notification('拾光记提醒已开启', { body: '重要任务会在提醒时间通知你。' }) } else messageApi.info('系统通知权限未开启') }
const sendTestNotification = () => { if (!('Notification' in window) || Notification.permission !== 'granted') return messageApi.warning('请先申请系统通知权限'); new Notification('拾光记测试通知', { body: '提醒通道工作正常。' }) }
const goalName = (id) => goals.value.find((item) => String(item.id) === String(id))?.goalName || '未关联目标'
onMounted(() => { const view = String(route.query.view || 'matrix'); activeView.value = ['matrix', 'today', 'completed', 'report', 'settings'].includes(view) ? view : 'matrix'; statusFilter.value = view === 'completed' ? 'DONE' : 'ACTIVE'; loadData() })
</script>

<template>
<div class="app-shell overflow-x-hidden" :class="isDark ? 'app-shell-dark' : 'app-shell-light'"><Nav :isDark="isDark" :menuItems="menuItems" /><main class="app-main"><div class="app-container space-y-5">
<header class="focus-header"><div><p class="app-section-label mb-2">Focus task</p><h1 class="app-page-title">任务矩阵</h1><p class="app-page-desc">把重要和紧急分开，今天只处理最值得推进的事情。</p></div><div class="focus-actions"><label class="focus-search"><Search class="h-4 w-4" /><input v-model="searchText" placeholder="搜索任务..." /></label><button type="button" class="app-btn-primary" @click="openCreate()"><Plus class="mr-1 inline h-4 w-4" />新任务</button></div></header>
<div v-if="error" class="focus-notice">{{ error }}</div>
<section class="focus-layout"><aside class="focus-sidebar app-card-surface"><div class="sidebar-group"><p class="sidebar-label">视图</p><button type="button" class="sidebar-item" :class="{ active: activeView === 'matrix' }" @click="goView('matrix')"><span class="sidebar-dot dot-blue"></span><span>四象限矩阵</span><b>{{ matrixCount }}</b></button><button type="button" class="sidebar-item" :class="{ active: activeView === 'today' }" @click="goView('today')"><span class="sidebar-dot dot-rose"></span><span>今日任务</span><b>{{ todayDueCount }}</b></button><button type="button" class="sidebar-item" :class="{ active: activeView === 'completed' }" @click="goView('completed')"><span class="sidebar-dot dot-slate"></span><span>已完成</span><b>{{ completedTasks.length }}</b></button></div><div class="sidebar-group"><p class="sidebar-label">象限</p><button v-for="quadrant in quadrants" :key="quadrant.key" type="button" class="sidebar-item compact" @click="goView('matrix')"><span class="sidebar-dot" :class="'dot-' + quadrant.tone"></span><span>{{ quadrant.label }}</span><b>{{ quadrantStats.find((item) => item.key === quadrant.key)?.total || 0 }}</b></button></div><div class="sidebar-group sidebar-bottom"><button type="button" class="sidebar-item" :class="{ active: activeView === 'report' }" @click="goView('report')"><span class="sidebar-icon"><Calendar class="h-4 w-4" /></span><span>完成报告</span></button><button type="button" class="sidebar-item" :class="{ active: activeView === 'settings' }" @click="goView('settings')"><span class="sidebar-icon"><Setting class="h-4 w-4" /></span><span>提醒设置</span></button></div></aside>
<section class="focus-content">
<template v-if="activeView === 'matrix'"><div class="focus-summary app-card-surface"><div><span class="focus-kicker">今日焦点</span><strong>{{ overdueCount ? overdueCount + ' 项逾期任务需要处理' : matrixCount + ' 项任务等待推进' }}</strong></div><div class="summary-metrics"><span><i class="dot-blue"></i>共 {{ matrixCount }} 项</span><span><i class="dot-green"></i>已完成 {{ completedTasks.length }} 项</span><span>完成率 {{ completionRate }}%</span></div></div><div class="matrix-grid"><article v-for="quadrant in quadrants" :key="quadrant.key" class="quadrant-panel" :class="'tone-' + quadrant.tone" @dragover.prevent @drop="dropToQuadrant($event, quadrant.key)"><header class="quadrant-header"><div><span class="quadrant-mark">●</span><h2>{{ quadrant.label }}</h2><small>{{ quadrant.subtitle }}</small></div><div class="quadrant-tools"><b>{{ quadrantTasks(quadrant.key).length }}</b><button type="button" aria-label="新建任务" title="在此象限新建任务" @click="openCreate(quadrant.key)"><Plus class="h-4 w-4" /></button></div></header><div v-if="quadrantTasks(quadrant.key).length" class="quadrant-list"><article v-for="task in quadrantTasks(quadrant.key)" :key="task.id" class="task-card" draggable="true" @dragstart="startDrag($event, task)" @click="editTask(task)"><button type="button" class="task-check" :class="{ done: task.status === 'DONE' }" aria-label="完成任务" @click.stop="saveStatus(task, task.status === 'DONE' ? 'TODO' : 'DONE')"><Check v-if="task.status === 'DONE'" class="h-3.5 w-3.5" /></button><div class="min-w-0 flex-1"><strong>{{ task.taskName || '未命名任务' }}</strong><small>{{ formatDate(task.dueDate) }} · {{ task.estimatedMinutes || 0 }} 分钟</small><span v-if="task.tags" class="task-tag">{{ task.tags }}</span></div><button type="button" class="task-more" aria-label="编辑任务" title="编辑任务" @click.stop="editTask(task)"><EditPen class="h-3.5 w-3.5" /></button></article></div><button v-else type="button" class="quadrant-empty" @click="openCreate(quadrant.key)"><Plus class="h-5 w-5" /><span>添加一项任务</span></button></article></div></template>
<template v-else-if="activeView === 'today' || activeView === 'completed'"><section class="app-card-surface focus-list-panel"><div class="panel-heading"><div><p class="app-section-label">{{ activeView === 'today' ? 'Today' : 'Archive' }}</p><h2>{{ activeView === 'today' ? '今日任务' : '已完成任务' }}</h2><p>{{ activeView === 'today' ? '截止今天或已经逾期的任务。' : '保留完成记录，方便复盘真实进展。' }}</p></div><button type="button" class="app-btn-primary" @click="openCreate()"><Plus class="mr-1 inline h-4 w-4" />新任务</button></div><div class="list-filters"><select v-model="statusFilter"><option value="ACTIVE">未完成</option><option value="DONE">已完成</option><option value="ALL">全部</option></select><span>{{ listTasks.length }} 项</span></div><div v-if="listTasks.length" class="focus-list"><article v-for="task in listTasks" :key="task.id" class="focus-list-row"><button type="button" class="task-check" :class="{ done: task.status === 'DONE' }" @click="saveStatus(task, task.status === 'DONE' ? 'TODO' : 'DONE')"><Check v-if="task.status === 'DONE'" class="h-3.5 w-3.5" /></button><div class="min-w-0 flex-1"><strong>{{ task.taskName || '未命名任务' }}</strong><small>{{ quadrantLabel(task.quadrant) }} · {{ formatDate(task.dueDate) }} · {{ goalName(task.goalId) }}</small></div><button type="button" class="mini-icon" title="编辑任务" aria-label="编辑任务" @click="editTask(task)"><EditPen class="h-4 w-4" /></button><button type="button" class="mini-icon danger" title="删除任务" aria-label="删除任务" @click="deleteTask(task)"><Delete class="h-4 w-4" /></button></article></div><div v-else class="focus-empty"><Check class="h-8 w-8" /><strong>{{ activeView === 'today' ? '今天没有待处理任务' : '还没有完成记录' }}</strong><span>{{ activeView === 'today' ? '把一个小行动放入矩阵，今天就有明确方向。' : '完成的任务会在这里留下时间证据。' }}</span></div></section></template>
<template v-else-if="activeView === 'report'"><section class="app-card-surface focus-list-panel"><div class="panel-heading"><div><p class="app-section-label">Report</p><h2>完成情况总览</h2><p>按时间范围查看完成节奏、主力象限和逾期任务。</p></div><div class="range-tabs"><button v-for="range in [['week','本周'],['month','本月'],['quarter','本季']]" :key="range[0]" type="button" :class="{ active: reportRange === range[0] }" @click="reportRange = range[0]">{{ range[1] }}</button></div></div><div class="report-stats"><article><span>已完成</span><strong>{{ completedTasks.length }}</strong><small>全部任务</small></article><article><span>活跃天数</span><strong>{{ activeDays }}</strong><small>当前范围</small></article><article><span>单日峰值</span><strong>{{ Math.max(0, ...reportDays.map((item) => item.done)) }}</strong><small>完成数</small></article><article><span>逾期任务</span><strong>{{ overdueCount }}</strong><small>尚未完成</small></article></div><div class="report-body"><div class="trend-panel"><div class="report-section-heading"><h3>完成任务趋势</h3><span>{{ reportDays.length }} 天</span></div><div class="trend-chart"><div v-for="day in reportDays" :key="day.key" class="trend-column"><span class="trend-bar" :style="{ height: Math.max(4, (day.done / maxReportDone) * 100) + '%' }"></span><small>{{ day.label }}</small></div></div></div><div class="distribution-panel"><div class="report-section-heading"><h3>象限构成</h3><span>完成 / 总数</span></div><div v-for="item in quadrantStats" :key="item.key" class="distribution-row"><div><span class="quadrant-mark" :class="'mark-' + item.tone">●</span><strong>{{ item.label }}</strong><b>{{ item.done }} / {{ item.total }}</b></div><div class="distribution-track"><i :class="'bar-' + item.tone" :style="{ width: (item.total ? (item.done / item.total) * 100 : 0) + '%' }"></i></div></div></div></div></section></template>
<template v-else><section class="settings-grid"><div class="app-card-surface focus-list-panel"><div class="panel-heading"><div><p class="app-section-label">Reminder</p><h2>提醒策略</h2><p>控制任务提醒频率和免打扰时段。</p></div><Bell class="panel-icon" /></div><label class="setting-row"><span><strong>启用提醒</strong><small>逾期任务、复习和面试提醒</small></span><input v-model="notificationPreference.enabled" type="checkbox" :true-value="1" :false-value="0" @change="savePreference" /></label><label class="setting-row"><span><strong>免打扰时段</strong><small>该时间内不发送提醒</small></span><input v-model="notificationPreference.quietHoursEnabled" type="checkbox" :true-value="1" :false-value="0" @change="savePreference" /></label><div class="time-grid"><label>免打扰开始<input v-model="notificationPreference.quietStart" type="time" @change="savePreference" /></label><label>免打扰结束<input v-model="notificationPreference.quietEnd" type="time" @change="savePreference" /></label><label>默认提前提醒<input v-model.number="notificationPreference.defaultReminderMinutes" type="number" min="0" max="1440" @change="savePreference" /></label><label>默认开始时间<input v-model="notificationPreference.defaultStartTime" type="time" @change="savePreference" /></label><label>默认结束时间<input v-model="notificationPreference.defaultEndTime" type="time" @change="savePreference" /></label></div><div class="settings-actions"><button type="button" class="app-btn-primary" @click="requestBrowserPermission">申请系统通知权限</button><button type="button" class="app-btn-secondary" @click="sendTestNotification">发送测试通知</button></div></div><div class="app-card-surface focus-list-panel"><div class="panel-heading"><div><p class="app-section-label">Task defaults</p><h2>象限参考</h2><p>新增任务默认进入重要且不紧急，也可以在编辑时调整。</p></div><Setting class="panel-icon" /></div><div class="default-guide"><div><span class="sidebar-dot dot-rose"></span><strong>重要 · 紧急</strong><small>截止临近，需要马上处理</small></div><div><span class="sidebar-dot dot-green"></span><strong>重要 · 不紧急</strong><small>安排时间，持续推进</small></div><div><span class="sidebar-dot dot-cyan"></span><strong>紧急 · 不重要</strong><small>尽量委托或快速处理</small></div><div><span class="sidebar-dot dot-slate"></span><strong>不重要 · 不紧急</strong><small>有空再处理或删除</small></div></div></div></section></template>
</section></section></div></main>
<div v-if="showForm" class="focus-overlay" @click.self="closeForm">
  <section class="focus-dialog app-card-surface" role="dialog" aria-modal="true" :aria-label="editingTask ? '编辑任务' : '新建任务'">
    <header class="dialog-header"><div class="dialog-title"><span><EditPen v-if="editingTask" /><Plus v-else /></span><div><p>{{ editingTask ? '编辑任务' : '新建任务' }}</p><small>{{ editingTask ? '调整任务信息与计划安排' : '创建一项明确、可执行的行动' }}</small></div></div><button type="button" class="dialog-close" aria-label="关闭" title="关闭" @click="closeForm">×</button></header>
    <div class="dialog-body">
      <section class="form-section"><p class="form-section-title">任务信息</p><label class="task-title-field"><span>任务标题 <b>*</b></span><input v-model="form.taskName" class="field" maxlength="180" autofocus placeholder="输入要完成的事情" /></label><div class="dialog-grid three-cols"><label>象限<select v-model="form.quadrant" class="field"><option v-for="quadrant in quadrants" :key="quadrant.key" :value="quadrant.key">{{ quadrant.label }} · {{ quadrant.subtitle }}</option></select></label><label>状态<select v-model="form.status" class="field"><option value="TODO">待处理</option><option value="DOING">推进中</option><option value="DONE">已完成</option></select></label><label>优先级<select v-model="form.priority" class="field"><option value="HIGH">高</option><option value="MEDIUM">中</option><option value="LOW">低</option></select></label></div></section>
      <section class="form-section"><p class="form-section-title">计划安排</p><div class="dialog-grid"><label>开始日期<input v-model="form.startDate" class="field" type="date" /></label><label>截止日期<input v-model="form.dueDate" class="field" type="date" /></label><label>预计用时（分钟）<input v-model.number="form.estimatedMinutes" class="field" min="0" type="number" /></label><label>关联目标<select v-model="form.goalId" class="field"><option :value="null">不关联目标</option><option v-for="goal in goals" :key="goal.id" :value="goal.id">{{ goal.goalName }}</option></select></label></div><div class="dialog-grid detail-grid"><label>标签<input v-model="form.tags" class="field" maxlength="255" placeholder="例如：项目、学习" /></label><label>备注<textarea v-model="form.notes" class="field" rows="2" placeholder="补充完成标准或必要说明"></textarea></label></div></section>
      <section class="form-section reminder-section" :class="{ enabled: form.reminderEnabled }"><label class="reminder-toggle"><span class="reminder-copy"><Bell /><span><strong>任务提醒</strong><small>在指定时间进入通知中心</small></span></span><input v-model="form.reminderEnabled" type="checkbox" :true-value="1" :false-value="0" /></label><div v-if="form.reminderEnabled" class="dialog-grid reminder-fields"><label>提醒时间<input v-model="form.reminderAt" class="field" type="datetime-local" /></label><label>重复规则<select v-model="form.repeatRule" class="field"><option value="NONE">不重复</option><option value="DAILY">每天</option><option value="WEEKLY">每周</option><option value="MONTHLY">每月</option></select></label></div></section>
    </div>
